#!/usr/bin/env node
// Fails when a command registered in `generate_handler!` is missing its Tauri
// ACL wiring: the COMMANDS list in build.rs, the autogenerated permission file,
// or the capability that actually allows it at runtime. Missing any of them
// throws "not allowed. Command not found" in the running app only.
import { existsSync, readFileSync } from "node:fs";

const lib = readFileSync("src-tauri/src/lib.rs", "utf8");
const build = readFileSync("src-tauri/build.rs", "utf8");
const capability = JSON.parse(readFileSync("src-tauri/capabilities/default.json", "utf8"));

const start = lib.indexOf("tauri::generate_handler![");
if (start < 0) {
  console.error("tauri acl: no tauri::generate_handler! in src-tauri/src/lib.rs");
  process.exit(1);
}
const open = lib.indexOf("[", start);
let depth = 0;
let end = -1;
for (let i = open; i < lib.length; i++) {
  if (lib[i] === "[") depth += 1;
  else if (lib[i] === "]" && --depth === 0) {
    end = i;
    break;
  }
}
const handlers = lib
  .slice(open + 1, end)
  .split(",")
  .map((entry) => entry.trim().split("::").pop())
  .filter(Boolean);

const listed = new Set([...build.slice(build.indexOf("const COMMANDS")).matchAll(/"([a-z0-9_]+)"/g)].map((m) => m[1]));
const allowed = new Set(capability.permissions);

const problems = [];
for (const name of handlers) {
  if (!listed.has(name)) problems.push(`${name}: missing from COMMANDS in src-tauri/build.rs`);
  const file = `src-tauri/permissions/autogenerated/${name}.toml`;
  if (!existsSync(file) || !readFileSync(file, "utf8").includes(`commands.allow = ["${name}"]`)) {
    problems.push(`${name}: missing or incomplete ${file}`);
  }
  const permission = `allow-${name.replaceAll("_", "-")}`;
  if (!allowed.has(permission)) {
    problems.push(`${name}: missing "${permission}" in src-tauri/capabilities/default.json`);
  }
}

if (problems.length > 0) {
  console.error("tauri acl: commands without a working permission:");
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exit(1);
}
console.log(`tauri acl: ${handlers.length} commands wired`);
